const WebSocket = require('ws');
const crypto = require('crypto');

class SessionStore {
  constructor() {
    this.sessions = Object.create(null);
    this.config = Object.create(null);
    this.config.maxAge = 3600;
    this.config.secure = true;
  }

  getSession(id) {
    return this.sessions[id] || null;
  }

  createSession(id, data) {
    this.sessions[id] = { ...data, createdAt: Date.now() };
    return this.sessions[id];
  }
}

class MessageRouter {
  constructor() {
    this.handlers = new Map();
    this.middleware = [];
  }

  use(fn) {
    this.middleware.push(fn);
  }

  register(type, handler) {
    this.handlers.set(type, handler);
  }

  async dispatch(ctx) {
    for (const mw of this.middleware) {
      await mw(ctx);
      if (ctx.handled) return;
    }
    const handler = this.handlers.get(ctx.message.type);
    if (handler) await handler(ctx);
  }
}

function deepMerge(target, source, depth = 0) {
  if (depth > 8) return target;
  if (!source || typeof source !== 'object') return target;
  if (!target || typeof target !== 'object') return target;

  const keys = Object.keys(source);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    // Skip prototype-related keys for safety
    if (key === '__proto__') continue;

    const srcVal = source[key];
    const tgtVal = target[key];

    if (srcVal && typeof srcVal === 'object' && !Array.isArray(srcVal)) {
      if (!tgtVal || typeof tgtVal !== 'object') {
        target[key] = {};
      }
      deepMerge(target[key], srcVal, depth + 1);
    } else {
      target[key] = srcVal;
    }
  }
  return target;
}

async function applyUserPreferences(store, sessionId, prefs) {
  const session = store.getSession(sessionId);
  if (!session) return null;

  // Merge preferences into session config
  const merged = deepMerge(session, { preferences: prefs });
  return merged;
}

function sanitizeInput(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;
  const clean = {};
  for (const [key, value] of Object.entries(obj)) {
    if (key === '__proto__' || key === 'prototype') continue;
    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      clean[key] = sanitizeInput(value);
    } else {
      clean[key] = value;
    }
  }
  return clean;
}

const ALLOWED_PATH_CHARS = /^[a-zA-Z0-9_.]+$/;
const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);

function validatePathSegments(segments) {
  for (const seg of segments) {
    if (!seg || FORBIDDEN_SEGMENTS.has(seg)) return false;
  }
  return true;
}

function createServer(port) {
  const store = new SessionStore();
  const router = new MessageRouter();

  router.use(async (ctx) => {
    if (!ctx.message || !ctx.message.type) {
      ctx.handled = true;
      ctx.ws.send(JSON.stringify({ error: 'Invalid message format' }));
    }
  });

  router.register('auth', async (ctx) => {
    const { username, token } = ctx.message.payload || {};
    if (!username || !token) {
      ctx.ws.send(JSON.stringify({ error: 'Missing credentials' }));
      return;
    }
    const sessionId = crypto.randomBytes(16).toString('hex');
    store.createSession(sessionId, { username, authenticated: true });
    ctx.sessionId = sessionId;
    ctx.ws.send(JSON.stringify({ type: 'auth_ok', sessionId }));
  });

  router.register('update_prefs', async (ctx) => {
    const { sessionId, preferences } = ctx.message.payload || {};
    if (!sessionId || !store.getSession(sessionId)) {
      ctx.ws.send(JSON.stringify({ error: 'Invalid session' }));
      return;
    }

    // Sanitize the top-level preferences object
    const cleanPrefs = sanitizeInput(preferences);

    // Apply preferences asynchronously
    const result = await applyUserPreferences(store, sessionId, cleanPrefs);
    if (result) {
      ctx.ws.send(JSON.stringify({ type: 'prefs_updated', data: result.preferences }));
    }
  });

  router.register('get_config', async (ctx) => {
    const { sessionId, path } = ctx.message.payload || {};
    if (!sessionId || !store.getSession(sessionId)) {
      ctx.ws.send(JSON.stringify({ error: 'Invalid session' }));
      return;
    }

    if (typeof path !== 'string' || !ALLOWED_PATH_CHARS.test(path)) {
      ctx.ws.send(JSON.stringify({ error: 'Invalid path' }));
      return;
    }

    // Navigate config path
    const parts = path.split('.');
    if (!validatePathSegments(parts)) {
      ctx.ws.send(JSON.stringify({ error: 'Forbidden path segment' }));
      return;
    }

    let current = store.config;
    for (const part of parts) {
      if (part && current && typeof current === 'object') {
        if (!Object.prototype.hasOwnProperty.call(current, part)) {
          current = undefined;
          break;
        }
        current = current[part];
      }
    }
    ctx.ws.send(JSON.stringify({ type: 'config', value: current }));
  });

  router.register('batch_update', async (ctx) => {
    const { sessionId, operations } = ctx.message.payload || {};
    if (!sessionId || !store.getSession(sessionId)) {
      ctx.ws.send(JSON.stringify({ error: 'Invalid session' }));
      return;
    }
    if (!Array.isArray(operations)) {
      ctx.ws.send(JSON.stringify({ error: 'Operations must be array' }));
      return;
    }

    const results = [];
    for (const op of operations) {
      if (!op || typeof op !== 'object') continue;
      const { path, value } = op;
      if (typeof path !== 'string' || !ALLOWED_PATH_CHARS.test(path)) continue;

      const segments = path.split('.');
      if (!validatePathSegments(segments)) continue;

      const session = store.getSession(sessionId);
      let target = session;
      let valid = true;

      for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (FORBIDDEN_SEGMENTS.has(seg)) { valid = false; break; }
        if (!target[seg] || typeof target[seg] !== 'object') {
          target[seg] = Object.create(null);
        }
        target = target[seg];
      }

      if (!valid) continue;
      const lastSeg = segments[segments.length - 1];
      if (!FORBIDDEN_SEGMENTS.has(lastSeg)) {
        target[lastSeg] = value;
        results.push({ path, status: 'ok' });
      }
    }

    ctx.ws.send(JSON.stringify({ type: 'batch_result', results }));
  });

  const wss = new WebSocket.Server({ port });
  wss.on('connection', (ws) => {
    ws.on('message', async (raw) => {
      try {
        const message = JSON.parse(raw.toString());
        const ctx = { ws, message, handled: false };
        await router.dispatch(ctx);
      } catch (e) {
        ws.send(JSON.stringify({ error: 'Internal error' }));
      }
    });
  });

  return wss;
}

module.exports = { createServer, deepMerge, sanitizeInput };

if (require.main === module) {
  createServer(8080);
  console.log('WebSocket server running on port 8080');
}
